using System.Collections.Generic;
using MessagePack;

public enum CardPoolType
{
    /// <summary>The stats exactly as the factory has them, regenerated by the DataGenerator.</summary>
    ORIGINAL,
    /// <summary>The stats the game plays with, these are the ones to edit for balancing.</summary>
    BALANCED
}

[MessagePackObject]
public class CardPool
{
    [Key(0)]
    public List<CardData> Cards { get; set; } = new();
}
